// Common-timeline public-output operator phase observer; no internal phase fields.
package main
import("crypto/sha256";"encoding/json";"flag";"fmt";"math";"os")
type zero_run struct{First int `json:"first"`;End int `json:"end_exclusive"`}
type exposure_fit struct{Operator string `json:"operator"`;First int `json:"first"`;End int `json:"end_exclusive"`;Samples int `json:"samples"`;Sin float64 `json:"sin_pcm"`;Cos float64 `json:"cos_pcm"`;DC float64 `json:"dc_pcm"`;Amplitude float64 `json:"peak_amplitude_pcm"`;Phase float64 `json:"unaligned_phase_radians"`;Relative float64 `json:"phase_relative_to_initial_M1_radians"`;Residual float64 `json:"rms_residual_pcm"`}
type phase_job struct{column,marker_column,marker_csv,order string;guard,minimum int}
func main(){var job phase_job;flag.StringVar(&job.column,"column","right","continuous PG timeline PCM");flag.StringVar(&job.marker_column,"marker-column","left","LEFTmarker PCM");flag.StringVar(&job.marker_csv,"marker-csv","","optional separate LEFTCSV");flag.StringVar(&job.order,"order","forward","forward|reverse|leak");flag.IntVar(&job.guard,"guard",128,"exclude entire LEFTzero run plus this each side");flag.IntVar(&job.minimum,"minimum",1000,"minimum accepted segment samples");flag.Parse();e:=job.run();if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func(job *phase_job)run()error{
 if flag.NArg()!=1||job.guard<0||job.minimum<256{return fmt.Errorf("invalid flags/input")};raw,e:=os.ReadFile(flag.Arg(0));if e!=nil{return e};v,e:=read_phase_csv(raw,job.column);if e!=nil{return e};marker:=raw;if job.marker_csv!=""{marker,e=os.ReadFile(job.marker_csv);if e!=nil{return e}};left,e:=read_phase_csv(marker,job.marker_column);if e!=nil{return e};if len(left)!=len(v){return fmt.Errorf("LEFT/RIGHTlength mismatch")};for i,x:=range v{if x!=math.Trunc(x)||left[i]!=math.Trunc(left[i]){return fmt.Errorf("nonintegralPCM")}}
 out:=map[string]interface{}{"input":flag.Arg(0),"input_sha256":fmt.Sprintf("%x",sha256.Sum256(raw)),"marker_input_sha256":fmt.Sprintf("%x",sha256.Sum256(marker)),"recorded_increment_20bit":32992,"native_stride":8,"assumptions":[]string{"One common native sample timeline; no inverse-sine amplitude8170 calibration","Fitted sine/cos/DC phases diagnose PG output only,not corrections inside complex algorithm fits","TL127leak and phase-quantization remain in observed residual; no exactinactive-mute assumption","Known OPMdynamic-pan caveat retained; marker-adjacent observations excluded"}}
 if job.order=="leak"{lo,hi:=v[0],v[0];square,zero:=0.,0;for _,x:=range v{lo=math.Min(lo,x);hi=math.Max(hi,x);square+=x*x;if x==0{zero++}};out["state"]="all4held_TL127_floor_measured_no_phase";out["extrema_pcm"]=[]float64{lo,hi};out["rms_pcm"]=math.Sqrt(square/float64(len(v)));out["exact_zero_fraction"]=float64(zero)/float64(len(v));out["phase"]=nil;return json.NewEncoder(os.Stdout).Encode(out)}
 order:=[]string{"M1","M2","C1","C2","M1"};if job.order=="reverse"{order=[]string{"M1","C2","C1","M2","M1"}}else if job.order!="forward"{return fmt.Errorf("invalid order")};runs:=find_runs(left);if len(runs)!=4{return fmt.Errorf("expected4LEFTzero runs,got%d",len(runs))};fits,e:=observe_phase(v,runs,order,job.guard,job.minimum);if e!=nil{return e};out["state"]="five_exposures_common_timeline_measured";out["left_zero_runs"]=runs;out["exposures"]=fits;out["M1return_phase_difference_radians"]=fits[4].Relative;out["marker_exclusion_samples_each_side"]=job.guard;return json.NewEncoder(os.Stdout).Encode(out)
}
func find_runs(v []float64)[]zero_run{out:=[]zero_run{};start:=-1;for n:=0;n<=len(v);n++{zero:=n<len(v)&&v[n]==0;if zero&&start<0{start=n};if !zero&&start>=0{if n-start>=16{out=append(out,zero_run{start,n})};start=-1}};return out}
func observe_phase(v []float64,runs []zero_run,order []string,guard,minimum int)([]exposure_fit,error){
 fits:=[]exposure_fit{};for i,op:=range order{first,end:=guard,len(v)-guard;if i>0{first=runs[i-1].End+guard};if i<4{end=runs[i].First-guard};if end-first<minimum{return nil,fmt.Errorf("%s has only%daccepted samples",op,end-first)};f,e:=fit_sine(v,first,end);if e!=nil{return nil,e};f.Operator=op;if f.Amplitude<32{return nil,fmt.Errorf("%s phase unobservable at low amplitude",op)};if len(fits)>0{f.Relative=math.Remainder(f.Phase-fits[0].Phase,2*math.Pi)};fits=append(fits,f)};return fits,nil
}
func fit_sine(v []float64,first,end int)(exposure_fit,error){
 r:=exposure_fit{First:first,End:end,Samples:end-first};var a [3][4]float64;w:=2*math.Pi*32992/(1<<20);for n:=first;n<end;n++{s,c:=math.Sincos(w*float64(n));basis:=[3]float64{s,c,1};for i:=0;i<3;i++{for j:=0;j<3;j++{a[i][j]+=basis[i]*basis[j]};a[i][3]+=basis[i]*v[n]}}
 for k:=0;k<3;k++{pivot:=k;for i:=k+1;i<3;i++{if math.Abs(a[i][k])>math.Abs(a[pivot][k]){pivot=i}};if math.Abs(a[pivot][k])<1e-10{return r,fmt.Errorf("singular sine basis")};a[k],a[pivot]=a[pivot],a[k];scale:=a[k][k];for j:=k;j<4;j++{a[k][j]/=scale};for i:=0;i<3;i++{if i==k{continue};d:=a[i][k];for j:=k;j<4;j++{a[i][j]-=d*a[k][j]}}};r.Sin,r.Cos,r.DC=a[0][3],a[1][3],a[2][3];r.Amplitude=math.Hypot(r.Sin,r.Cos);r.Phase=math.Atan2(r.Cos,r.Sin);sum:=0.;for n:=first;n<end;n++{s,c:=math.Sincos(w*float64(n));d:=v[n]-(r.Sin*s+r.Cos*c+r.DC);sum+=d*d};r.Residual=math.Sqrt(sum/float64(end-first));return r,nil
}
